{
  "title": "太空求生：未知信号",
  "scene": "你所在的太空飞船突然遭遇故障，氧气供应迅速下降。控制台上闪烁着一个未知信号的提示，显示来自不远处的一颗未知行星。船上的工程师试图修复氧气系统，但需要时间。此时，你有两个选择：发送求救信号给未知信号源或是尝试手动启动备用氧气罐。控制台上的屏幕显示出备用氧气罐的激活按钮已被锁定，需要一个特定的代码才能解锁。而未知信号的详细信息中，似乎有一串数字与备用氧气罐的代码相似。",
  "goal": "尽快找到或创造额外的氧气来源，确保生存。",
  "clue": "未知信号的详细信息中有一串数字与备用氧气罐的解锁代码相似。",
  "choices": [
    {
      "id": "A",
      "text": "发送求救信号",
      "outcome": "你在发送求救信号后，等待了很长时间，工程师终于修复了氧气系统，但氧气已经消耗至危险水平，你和船员们都感到极度虚弱。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "尝试手动启动备用氧气罐",
      "outcome": "你试图手动启动备用氧气罐，但按钮被锁，没有成功。氧气水平继续下降，必须再次尝试其他方法。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "检查未知信号的数字",
      "outcome": "你仔细检查了未知信号中的数字，并发现它们确实是备用氧气罐的解锁代码。成功输入代码后，备用氧气罐启动，为船员们提供了足够的氧气，工程师也顺利完成了修复工作。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
